const rows = $input.all().map(i => i.json);
const hasBaseline = rows.length > 0 && Number(rows[0].snapshot_count) >= 2;

const fmt = (r) => {
  if (r.metric_name === 'romi') return `ROMI (${r.metric_key}): ${Math.round(r.current_value * 100)}%${hasBaseline ? ` (${r.delta >= 0 ? '+' : ''}${Math.round(r.delta * 100)} \u043f.\u043f.)` : ''}`;
  if (r.metric_name === 'avg_ltv') return `LTV (\u0441\u0440\u0435\u0434\u043d\u0438\u0439): ${r.current_value}${hasBaseline ? ` (${r.delta >= 0 ? '+' : ''}${r.delta})` : ''}`;
  if (r.metric_name === 'retention_m1') return `Retention M1: ${Math.round(r.current_value * 100)}%${hasBaseline ? ` (${r.delta >= 0 ? '+' : ''}${Math.round(r.delta * 100)} \u043f.\u043f.)` : ''}`;
  return `${r.metric_name}/${r.metric_key}: ${r.current_value}`;
};
const raw_lines = rows.map(fmt);

const biggestMove = hasBaseline
  ? rows.reduce((a, b) => Math.abs(b.delta) > Math.abs(a.delta) ? b : a)
  : null;

const prompt = hasBaseline
  ? `\u0422\u044b \u2014 \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u043a. \u0412\u043e\u0442 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0431\u0438\u0437\u043d\u0435\u0441-\u043c\u0435\u0442\u0440\u0438\u043a \u0437\u0430 \u043f\u0435\u0440\u0438\u043e\u0434:\n${raw_lines.join('\n')}\n\n\u041d\u0430\u043f\u0438\u0448\u0438 2-3 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043d\u0430 \u0440\u0443\u0441\u0441\u043a\u043e\u043c: \u043a\u0430\u043a\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0441\u0430\u043c\u043e\u0435 \u0437\u0430\u043c\u0435\u0442\u043d\u043e\u0435 \u0438 \u0447\u0442\u043e \u0441\u0442\u043e\u0438\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c. \u0411\u0435\u0437 \u0432\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0439, \u0441\u0440\u0430\u0437\u0443 \u043f\u043e \u0434\u0435\u043b\u0443.`
  : null;

return [{ json: { has_baseline: hasBaseline, raw_lines, prompt } }];

const raw_lines = $('Build digest data').item.json.raw_lines;
const hasBaseline = $('Build digest data').item.json.has_baseline;
let aiSummary = '';
if (hasBaseline) {
  const resp = $input.first().json;
  // Ollama (/api/generate) -> {response}; Groq (OpenAI-\u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u044b\u0439) -> {choices[0].message.content}
  aiSummary = (resp.response || resp.choices?.[0]?.message?.content || '').trim();
}
const header = '\ud83d\udcc8 Weekly Report';
const body = raw_lines.join('\n');
const summarySection = aiSummary ? `\n\n\u26a0\ufe0f ${aiSummary}` : (hasBaseline ? '' : '\n\n(\u043f\u0435\u0440\u0432\u044b\u0439 \u0437\u0430\u043f\u0443\u0441\u043a \u2014 \u0431\u0430\u0437\u044b \u0434\u043b\u044f \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u0435\u0449\u0451 \u043d\u0435\u0442)');
const message = `${header}\n\n${body}${summarySection}`;
return [{ json: { message } }];
